const cartModule = {
  namespaced: true,
  state: () => ({ lines: [] as string[] }),
  mutations: {
    add(state: { lines: string[] }, id: string) {
      state.lines.push(id) // Vuex: sync mutation only
    },
  },
}
export const useCartStore = defineStore('cart', {
  state: () => ({ lines: [] as string[] }),
  actions: {
    add(id: string) {
      this.lines.push(id) // Pinia: the action is the writer
    },
  },
})

