// Vuex: dispatch → action → commit → mutation (sync) → state
const mutations = {
  SET_USER(state: { user: User | null }, user: User) {
    state.user = user // no await — DevTools replays this
  },
}
const actions = {
  async fetchUser({ commit }: { commit: Function }, id: string) {
    commit('SET_USER', await api.getUser(id))
  },
}

// Pinia: the action is the writer. No commit.
export const useUserStore = defineStore('user', {
  state: () => ({ user: null as User | null }),
  actions: {
    async fetchUser(id: string) {
      this.user = await api.getUser(id)
    },
  },
})

