// ❌ module-scope pinia — User A leaks into User B (pollution)
export const pinia = createPinia()

// ✅ one pinia per request; serialise pinia.state.value into the payload
export async function renderOk(cookie: string) {
  const pinia = createPinia()
  const app = createSSRApp(Root)
  app.use(pinia)
  useAuthStore(pinia).hydrateFrom(cookie)
  const html = await renderToString(app)
  return { html, state: pinia.state.value }
}

