async function renameProduct(id: string, name: string) {
  await $fetch(`/api/products/${id}`, {
    method: 'PATCH',
    body: { name },
  })
  // invalidate the server cache — do not store.items.push
  await refreshNuxtData(`product:${id}`)
  await refreshNuxtData('product-list')
  useUiStore().lastSavedAt = Date.now() // client-only overlay
}

